[InitializeOnLoad]public static class FinalSunkenUnderpasses{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",PrefabPath="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/SunkenUnderpasses";
static FinalSunkenUnderpasses(){EditorApplication.update+=Poll;}static void Poll(){if(File.Exists("FinalSunkenRefresh.request")&&!EditorApplication.isCompiling&&!EditorApplication.isPlayingOrWillChangePlaymode){File.Delete("FinalSunkenRefresh.request");AssetDatabase.Refresh();return;}if(!File.Exists("FinalSunkenUnderpasses.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;string mode=File.ReadAllText("FinalSunkenUnderpasses.request").Trim();File.Delete("FinalSunkenUnderpasses.request");if(mode=="preview")Preview();else if(mode=="finish")Finish();else if(mode=="repair")Repair();else if(mode=="refine")Refine();else if(mode=="finalcheck")FinalCheck();else Run();}
class D{public Vector3[] p;public Vector2[] uv,uv1;public int[] ids;public bool second;}
struct V{public Vector3 p;public Vector2 u,v;public V(Vector3 p,Vector2 u,Vector2 v){this.p=p;this.u=u;this.v=v;}}
class Row{public V a,b;}
class Site{public string left,right,junction;public MeshFilter a,b,j;public bool x;public float center,start,end,gapA,gapB,side,y,width;public List<Row> rows=new List<Row>();public Vector3 Dir=>x?Vector3.right:Vector3.forward;public Vector3 Side=>x?Vector3.forward:Vector3.right;public float L(Vector3 p)=>x?p.x:p.z;public float C(Vector3 p)=>x?p.z:p.x;public Vector3 P(float l,float c,float h)=>x?new Vector3(l,h,c):new Vector3(c,h,l);public float Dip(float l){if(l<start||l>end)return 0;if(l>=gapA&&l<=gapB)return 6.0f;float t=l<gapA?(l-start)/(gapA-start):(end-l)/(end-gapB);return 6.0f*(.5f-.5f*Mathf.Cos(Mathf.PI*Mathf.Clamp01(t)));}}
class Change{public MeshFilter f;public Mesh mesh;}
class B{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> ids=new List<int>();public void Q(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int n=p.Count;p.AddRange(new[]{a,b,c,d});float w=Vector3.Distance(a,b)/3,h=Vector3.Distance(a,d)/3;uv.AddRange(new[]{Vector2.zero,new Vector2(w,0),new Vector2(w,h),new Vector2(0,h)});ids.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}public void Box(Vector3 center,Vector3 size,Quaternion q){var r=q*Vector3.right*size.x/2;var u=q*Vector3.up*size.y/2;var f=q*Vector3.forward*size.z/2;var a=new[]{center-u-r-f,center-u+r-f,center-u+r+f,center-u-r+f};var b=a.Select(v=>v+u*2).ToArray();for(int k=0;k<4;k++){int j=(k+1)%4;Q(a[j],a[k],b[k],b[j]);}Q(a[0],a[1],a[2],a[3]);Q(b[3],b[2],b[1],b[0]);}}
static T Val<T>(object o,string n)=>(T)o.GetType().GetField(n).GetValue(o);
static D Read(MeshFilter f){var o=typeof(FinalPathwayRepair).GetMethod("Read",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{f.sharedMesh});return new D{p=Val<Vector3[]>(o,"p").Select(f.transform.TransformPoint).ToArray(),uv=Val<Vector2[]>(o,"uv"),uv1=Val<Vector2[]>(o,"uv1"),ids=Val<int[]>(o,"ids"),second=Val<bool>(o,"second")};}
static bool Height(D d,Vector3 p,out float y){var a=new object[]{d.p,d.ids,p,0f};bool result=(bool)typeof(FinalPathwayRepair).GetMethod("Height",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,a);y=(float)a[3];return result;}
static V Lerp(V a,V b,float t)=>new V(Vector3.Lerp(a.p,b.p,t),Vector2.Lerp(a.u,b.u,t),Vector2.Lerp(a.v,b.v,t));
static List<V> Clip(List<V> poly,Func<Vector3,float> distance,bool positive){var r=new List<V>();if(poly.Count<3)return r;V a=poly[poly.Count-1];float da=distance(a.p);bool ina=positive?da>=-.00001f:da<=.00001f;foreach(var b in poly){float db=distance(b.p);bool inb=positive?db>=-.00001f:db<=.00001f;if(ina!=inb)r.Add(Lerp(a,b,da/(da-db)));if(inb)r.Add(b);a=b;da=db;ina=inb;}return r;}
static void Fan(List<V> poly,List<V> output){for(int k=1;k<poly.Count-1;k++){if(Vector3.Cross(poly[k].p-poly[0].p,poly[k+1].p-poly[0].p).sqrMagnitude<.00000001f)continue;output.Add(poly[0]);output.Add(poly[k]);output.Add(poly[k+1]);}}
static Mesh Save(List<V> vertices,Transform tr,string name,bool uv1){var m=new Mesh{name=name};if(vertices.Count>65535)m.indexFormat=IndexFormat.UInt32;m.SetVertices(vertices.Select(v=>tr.InverseTransformPoint(v.p)).ToList());m.SetUVs(0,vertices.Select(v=>v.u).ToList());if(uv1)m.SetUVs(1,vertices.Select(v=>v.v).ToList());m.SetTriangles(Enumerable.Range(0,vertices.Count).ToArray(),0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();return Store(m,name);}
static Mesh Store(Mesh m,string name){string path=Out+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
static Mesh BufferMesh(B b,Transform tr,string name){var m=new Mesh{name=name};m.SetVertices(b.p.Select(tr.InverseTransformPoint).ToList());m.SetUVs(0,b.uv);m.SetTriangles(b.ids,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();return Store(m,name);}
static Row Cross(Site s,D d,float l){var edges=new List<V>();for(int k=0;k<d.ids.Length;k+=3)for(int q=0;q<3;q++){int ia=d.ids[k+q],ib=d.ids[k+(q+1)%3];var a=new V(d.p[ia],d.uv[ia],d.uv1[ia]);var b=new V(d.p[ib],d.uv[ib],d.uv1[ib]);float da=s.L(a.p)-l,db=s.L(b.p)-l;if(Mathf.Abs(da)<.005f)edges.Add(a);if(da*db<0)edges.Add(Lerp(a,b,da/(da-db)));}if(edges.Count<2)throw new Exception("Cross section missing at "+l);return new Row{a=edges.OrderBy(v=>s.C(v.p)).First(),b=edges.OrderByDescending(v=>s.C(v.p)).First()};}
static Site Define(GameObject root,string left,string right,string junction,bool built=false){var fs=root.GetComponentsInChildren<MeshFilter>(true);var s=new Site{left=left,right=right,junction=junction,a=fs.Single(f=>f.name==left),b=fs.Single(f=>f.name==right),j=fs.Single(f=>f.name==junction)};var ba=s.a.GetComponent<Renderer>().bounds;var bb=s.b.GetComponent<Renderer>().bounds;var bj=s.j.GetComponent<Renderer>().bounds;s.x=ba.size.x>ba.size.z;s.gapA=s.L(ba.max)-(built?0:4);s.gapB=s.L(bb.min)+(built?0:4);s.center=(s.gapA+s.gapB)/2;s.side=(s.C(ba.center)+s.C(bb.center))/2;s.y=bj.center.y;float ramp=Mathf.Min(95,Mathf.Floor(Mathf.Min(s.L(ba.max)-s.L(ba.min),s.L(bb.max)-s.L(bb.min))-(built?8:12)));s.start=s.gapA-ramp;s.end=s.gapB+ramp;s.width=Mathf.Max(s.x?ba.size.z:ba.size.x,s.x?bb.size.z:bb.size.x);if(s.start<s.L(ba.min)+5||s.end>s.L(bb.max)-5)throw new Exception("Insufficient ramp length on "+left+" / "+right);if(s.gapB-s.gapA<25||s.gapB-s.gapA>60)throw new Exception("Unexpected junction span.");var da=Read(s.a);var db=Read(s.b);var cuts=new SortedSet<float>{s.start,s.end,s.gapA,s.gapB};for(float l=s.start;l<s.end;l+=4)cuts.Add(l);var edgeA=Cross(s,da,s.gapA-.002f);var edgeB=Cross(s,db,s.gapB+.002f);foreach(float l in cuts){Row r;if(l<s.gapA)r=Cross(s,da,l);else if(l>s.gapB)r=Cross(s,db,l);else{float t=Mathf.InverseLerp(s.gapA,s.gapB,l);r=new Row{a=Lerp(edgeA.a,edgeB.a,t),b=Lerp(edgeA.b,edgeB.b,t)};}if(!built){r.a.p.y-=s.Dip(l);r.b.p.y-=s.Dip(l);}s.rows.Add(r);}return s;}
static Mesh Lower(MeshFilter f,Site s){var d=Read(f);var result=new List<V>();var cuts=s.rows.Select(r=>s.L(r.a.p)).ToArray();for(int k=0;k<d.ids.Length;k+=3){var pieces=new List<List<V>>{new List<V>{new V(d.p[d.ids[k]],d.uv[d.ids[k]],d.uv1[d.ids[k]]),new V(d.p[d.ids[k+1]],d.uv[d.ids[k+1]],d.uv1[d.ids[k+1]]),new V(d.p[d.ids[k+2]],d.uv[d.ids[k+2]],d.uv1[d.ids[k+2]])}};pieces=pieces.Select(p=>Clip(p,v=>s.L(v)-(f==s.a?s.gapA:s.gapB),f!=s.a)).Where(p=>p.Count>=3).ToList();foreach(float cut in cuts){var next=new List<List<V>>();foreach(var p in pieces){if(p.Min(v=>s.L(v.p))<cut-.0001f&&p.Max(v=>s.L(v.p))>cut+.0001f){next.Add(Clip(p,v=>s.L(v)-cut,true));next.Add(Clip(p,v=>s.L(v)-cut,false));}else next.Add(p);}pieces=next;}foreach(var p in pieces){for(int i=0;i<p.Count;i++){var v=p[i];v.p.y-=s.Dip(s.L(v.p));p[i]=v;}Fan(p,result);}}return Save(result,f.transform,"Lowered_"+f.name,d.second);}
static float SideEdge(Site s,float l,bool right){int i=1;while(i<s.rows.Count-1&&s.L(s.rows[i].a.p)<l)i++;var a=s.rows[i-1];var b=s.rows[i];float t=Mathf.InverseLerp(s.L(a.a.p),s.L(b.a.p),l);return Mathf.Lerp(s.C(right?a.b.p:a.a.p),s.C(right?b.b.p:b.a.p),t);}
static Mesh Carve(MeshFilter f,Site s,out bool changed,bool anyHeight=false){var d=Read(f);var result=new List<V>();changed=false;float cmin=s.rows.Min(r=>s.C(r.a.p))-.02f,cmax=s.rows.Max(r=>s.C(r.b.p))+.02f;foreach(int k in Enumerable.Range(0,d.ids.Length/3).Select(v=>v*3)){var poly=new List<V>();for(int j=0;j<3;j++){int i=d.ids[k+j];poly.Add(new V(d.p[i],d.uv[i],d.uv1[i]));}if(!anyHeight&&(poly.Min(v=>v.p.y)>s.y+.5f||poly.Max(v=>v.p.y)<s.y-.5f)){Fan(poly,result);continue;}var inside=poly;foreach(var cut in new Func<Vector3,float>[] {p=>s.L(p)-s.start,p=>s.end-s.L(p),p=>s.C(p)-(SideEdge(s,s.L(p),false)-(anyHeight?1.2f:.01f)),p=>SideEdge(s,s.L(p),true)+(anyHeight?1.2f:.01f)-s.C(p)}){var outside=Clip(inside,cut,false);Fan(outside,result);inside=Clip(inside,cut,true);if(inside.Count<3)break;}if(inside.Count>=3&&inside.Max(v=>s.L(v.p))>s.start+.5f&&inside.Min(v=>s.L(v.p))<s.end-.5f)changed=true;else if(inside.Count>=3)Fan(inside,result);}return changed?Save(result,f.transform,"Carved_"+f.name+"_"+s.junction,d.second):null;}
static void Assign(MeshFilter f,Mesh m){f.sharedMesh=m;foreach(var c in f.GetComponents<MeshCollider>()){c.sharedMesh=null;c.sharedMesh=m;}PrefabUtility.RecordPrefabInstancePropertyModifications(f);foreach(var c in f.GetComponents<MeshCollider>())PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
static Renderer Part(Transform parent,Mesh m,Material mat,string name,bool collision){var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=m;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic);if(collision)g.AddComponent<MeshCollider>().sharedMesh=m;return r;}
static void BoxColliderAt(Transform p,Vector3 center,Vector3 size,Quaternion q,string name){var g=new GameObject(name);g.transform.SetParent(p,false);g.transform.SetPositionAndRotation(center,q);g.AddComponent<BoxCollider>().size=size;}
static int Make(Site s,Transform group,Transform coordinates,int index,Material concrete,Material trim,Material road){var module=new GameObject("Sunken Underpass "+index+" - "+s.junction);module.transform.SetParent(group,false);var wall=new B();var edge=new B();var rot=Quaternion.LookRotation(s.Dir);var floor=new List<V>();
for(int i=1;i<s.rows.Count;i++){var a=s.rows[i-1];var b=s.rows[i];float l0=s.L(a.a.p),l1=s.L(b.a.p);if(l0>=s.gapA-.005f&&l1<=s.gapB+.005f){var quad=new List<V>{a.a,b.a,b.b,a.b};if(s.x)quad.Reverse();Fan(quad,floor);}foreach(int sign in new[]{-1,1}){var pa=sign<0?a.a.p:a.b.p;var pb=sign<0?b.a.p:b.b.p;var outSide=s.Side*sign;float top=s.y+.75f;Vector3 a0=pa-Vector3.up*.35f,b0=pb-Vector3.up*.35f,a1=new Vector3(pa.x,top,pa.z),b1=new Vector3(pb.x,top,pb.z);Vector3 a2=a1+outSide*.8f,b2=b1+outSide*.8f;Vector3 a3=a0+outSide*.8f,b3=b0+outSide*.8f;if(s.x?sign>0:sign<0){wall.Q(a1,b1,b0,a0);wall.Q(a3,b3,b2,a2);}else{wall.Q(a0,b0,b1,a1);wall.Q(a2,b2,b3,a3);}wall.Q(a1,b1,b2,a2);wall.Q(a3,b3,b0,a0);if(i==1)wall.Q(a3,a0,a1,a2);if(i==s.rows.Count-1)wall.Q(b0,b3,b2,b1);
var segment=pb-pa;float height=top-Mathf.Min(pa.y,pb.y)+.35f;BoxColliderAt(module.transform,(pa+pb)/2+outSide*.4f+Vector3.up*(top-(pa.y+pb.y)/2)/2,new Vector3(.8f,height,segment.magnitude+.03f),Quaternion.LookRotation(s.Dir),"Retaining wall collision");
var curbA=pa+outSide*-.18f+Vector3.up*.12f;var curbB=pb+outSide*-.18f+Vector3.up*.12f;edge.Box((curbA+curbB)/2,new Vector3(.32f,.24f,Vector3.Distance(curbA,curbB)+.01f),Quaternion.LookRotation(curbB-curbA));}}
float roofLength=s.gapB-s.gapA;float roofWidth=s.rows.Where(r=>s.L(r.a.p)>=s.gapA-.01f&&s.L(r.a.p)<=s.gapB+.01f).Max(r=>Vector3.Distance(r.a.p,r.b.p))+.8f;var roofCenter=s.P(s.center,s.side,s.y-.42f);wall.Box(roofCenter,new Vector3(roofWidth,.8f,roofLength),rot);BoxColliderAt(module.transform,roofCenter,new Vector3(roofWidth,.8f,roofLength),rot,"Upper crossing roof collision");
foreach(float l in new[]{s.gapA,s.gapB}){var r=s.rows.OrderBy(row=>Mathf.Abs(s.L(row.a.p)-l)).First();var p=(r.a.p+r.b.p)/2;float h=s.y-p.y;foreach(int sign in new[]{-1,1}){var v=sign<0?r.a.p:r.b.p;edge.Box(v+s.Side*sign*.4f+Vector3.up*(h/2),new Vector3(1.1f,h+.5f,1.1f),rot);}edge.Box(s.P(l,s.side,s.y-.25f),new Vector3(roofWidth+1,.5f,.8f),rot);}
var floorMesh=Save(floor,coordinates,"Underpass_"+index+"_Lower_Crossing",false);Part(module.transform,floorMesh,road,"Lower road beneath upper junction",true);var wallMesh=BufferMesh(wall,coordinates,"Underpass_"+index+"_Retaining_Concrete");var trimMesh=BufferMesh(edge,coordinates,"Underpass_"+index+"_Curbs_And_Portal");Part(module.transform,wallMesh,concrete,"Retaining walls and covered crossing",false);Part(module.transform,trimMesh,trim,"Curbs and portal edges",false);return floor.Count/3+wall.ids.Count/3+edge.ids.Count/3;}
static Site[] Sites(GameObject root)=>new[]{Define(root,"polySurface853","polySurface838","polySurface906"),Define(root,"polySurface863","polySurface871","polySurface923")};
static int Validate(GameObject root,Site[] sites){Physics.SyncTransforms();int checks=0;foreach(var s in sites)foreach(var row in s.rows){var center=(row.a.p+row.b.p)/2;foreach(float offset in new[]{-10.5f,-3.5f,3.5f,10.5f}){var p=center+s.Side*offset;var floors=Physics.RaycastAll(p+Vector3.up*.7f,Vector3.down,1.5f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(root.transform)).OrderBy(h=>h.distance).ToArray();if(floors.Length==0||Mathf.Abs(floors[0].point.y-p.y)>.15f)throw new Exception("Lower floor missing/masked at "+p+" junction="+s.junction+" hit="+(floors.Length>0?floors[0].collider.name:"none"));var obstruction=Physics.OverlapCapsule(p+Vector3.up*1.7f,p+Vector3.up*2,1.5f,~0,QueryTriggerInteraction.Ignore).FirstOrDefault(c=>c.transform.IsChildOf(root.transform));if(obstruction)throw new Exception("Driving space blocked at "+p+" by "+obstruction.name+" bounds="+obstruction.bounds);checks++;}}
return checks;}
static void Run(){var log=new StringBuilder();GameObject stage=null;MeshFilter originalWater=null;Mesh dryWater=null;bool saved=false;try{var scene=SceneManager.GetSceneByPath(ScenePath);if(!scene.isLoaded)throw new Exception("Final scene not open.");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");if(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Sunken Road Underpasses"))throw new Exception("Underpasses already built.");Directory.CreateDirectory(Out);Directory.CreateDirectory("FinalEnvironmentRoadBackup");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeSunkenUnderpasses-"+stamp+".unity",true);File.Copy(PrefabPath,"FinalEnvironmentRoadBackup/BeforeSunkenUnderpasses-"+stamp+".prefab");AssetDatabase.Refresh();stage=UnityEngine.Object.Instantiate(root);stage.name="Sunken Underpass Staging";SceneManager.MoveGameObjectToScene(stage,scene);if(PrefabUtility.IsPartOfPrefabInstance(stage))PrefabUtility.UnpackPrefabInstance(stage,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var sites=Sites(stage);var changes=new List<Change>();var concrete=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/Tunnel Concrete.mat");var trim=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/Portal Stone.mat");var road=sites[0].a.GetComponent<MeshRenderer>().sharedMaterial;var group=new GameObject("Sunken Road Underpasses");group.transform.SetParent(stage.transform,false);int triangles=0;
for(int i=0;i<sites.Length;i++){var s=sites[i];foreach(var f in new[]{s.a,s.b}){var m=Lower(f,s);Assign(f,m);changes.Add(new Change{f=f,mesh=m});}foreach(var f in stage.GetComponentsInChildren<MeshFilter>(true).Where(f=>f!=s.a&&f!=s.b&&f!=s.j&&f.GetComponent<Renderer>()&&f.sharedMesh&&f.sharedMesh.subMeshCount==1&&f.GetComponent<Renderer>().sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name=="Pathways"))).ToArray()){var bounds=f.GetComponent<Renderer>().bounds;if(s.L(bounds.max)<s.start||s.L(bounds.min)>s.end||s.C(bounds.max)<s.side-s.width/2-1||s.C(bounds.min)>s.side+s.width/2+1||bounds.min.y>s.y+.5f||bounds.max.y<s.y-.5f)continue;var m=Carve(f,s,out bool changed);if(changed){Assign(f,m);changes.Add(new Change{f=f,mesh=m});}}
triangles+=Make(s,group.transform,stage.transform,i+1,concrete,trim,road);log.AppendLine("Underpass "+(i+1)+" lower roads="+s.left+" / "+s.right+" upper junction="+s.junction+" center="+s.P(s.center,s.side,s.y)+" depth=6.0m; clearance=5.2m; covered length="+(s.gapB-s.gapA)+"m; ramp length="+(s.gapA-s.start)+"m each; maximum grade="+(6.0f*Mathf.PI/(2*(s.gapA-s.start))*100).ToString("F2")+"%.");}
int probes=Validate(stage,sites);if(group.GetComponentsInChildren<Light>(true).Length>0||triangles>12000)throw new Exception("Mobile geometry budget exceeded.");
originalWater=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).FirstOrDefault(f=>f.name=="Water");if(originalWater){var wetGo=new GameObject("Water Underpass Mask Staging");wetGo.transform.SetParent(stage.transform,false);wetGo.transform.SetPositionAndRotation(originalWater.transform.position,originalWater.transform.rotation);wetGo.transform.localScale=originalWater.transform.lossyScale;var wet=wetGo.AddComponent<MeshFilter>();wet.sharedMesh=originalWater.sharedMesh;foreach(var s in sites){var mask=Carve(wet,s,out bool changed,true);if(changed)wet.sharedMesh=mask;}dryWater=wet.sharedMesh;var d=Read(wet);foreach(var s in sites)foreach(var row in s.rows)foreach(float t in new[]{.1f,.5f,.9f}){var p=Vector3.Lerp(row.a.p,row.b.p,t);if(Height(d,p,out float y)&&y>p.y+.02f)throw new Exception("Water overlaps lower road at "+p);}log.AppendLine("Water mesh masked beneath both lowered road corridors; existing water material preserved.");}
var prefab=PrefabUtility.LoadPrefabContents(PrefabPath);try{foreach(var change in changes){var f=prefab.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name==change.f.name);Assign(f,change.mesh);}var obsolete=prefab.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Final Environment Underpasses");if(obsolete)UnityEngine.Object.DestroyImmediate(obsolete.gameObject);var copy=UnityEngine.Object.Instantiate(group,prefab.transform,false);copy.name=group.name;PrefabUtility.SaveAsPrefabAsset(prefab,PrefabPath,out bool ok);if(!ok)throw new Exception("Prefab save failed.");saved=true;}finally{PrefabUtility.UnloadPrefabContents(prefab);}
foreach(var change in changes){var f=root.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name==change.f.name);Assign(f,change.mesh);}if(originalWater&&dryWater)Assign(originalWater,dryWater);UnityEngine.Object.DestroyImmediate(stage);stage=null;AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed.");log.AppendLine("SUCCESS: two sunken road underpasses; added triangles="+triangles+"; geometry/collider checks="+probes+"; road and pavement meshes adjusted="+changes.Count+"; six combined structure renderers; existing materials only; new textures=0; new lights=0; scene and Final Roads prefab saved. Phone frame timing unmeasured.");
}catch(Exception e){log.AppendLine("FAILED "+e+" prefabSaved="+saved);Debug.LogException(e);}finally{if(stage)UnityEngine.Object.DestroyImmediate(stage);File.WriteAllText("FinalEnvironmentRoadReview/SunkenUnderpassesReport.txt",log.ToString());}}
static void Finish(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var sites=new[]{Define(root,"polySurface853","polySurface838","polySurface906",true),Define(root,"polySurface863","polySurface871","polySurface923",true)};for(int i=0;i<2;i++){var s=sites[i];var module=root.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Sunken Underpass "+(i+1)+" - "+s.junction);var f=module.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name=="Lower road beneath upper junction");var d=Read(f);var source=Read(s.a);var edge=Cross(s,source,s.gapA-.002f);var before=Cross(s,source,s.gapA-4);var ua=(edge.a.u-before.a.u)/3.998f;var ub=(edge.b.u-before.b.u)/3.998f;var vs=new List<V>();foreach(int index in d.ids){var p=d.p[index];float t=Mathf.InverseLerp(SideEdge(s,s.L(p),false),SideEdge(s,s.L(p),true),s.C(p));var uv=Vector2.Lerp(edge.a.u,edge.b.u,t)+Vector2.Lerp(ua,ub,t)*(s.L(p)-s.gapA);vs.Add(new V(p,uv,Vector2.zero));}var m=Save(vs,f.transform,"Underpass_"+(i+1)+"_Lower_Crossing",false);Assign(f,m);log.AppendLine("Crossing road UV repetition corrected: "+s.junction);}
