static void Repair(){var log=new StringBuilder();GameObject stage=null;bool committed=false;try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");if(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Continuous underpass roadway"))throw new Exception("Continuous repair already installed; inspect before re-running.");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeUnderpassRepair-"+stamp+".unity",true);File.Copy(PrefabPath,"FinalEnvironmentRoadBackup/BeforeUnderpassRepair-"+stamp+".prefab");stage=UnityEngine.Object.Instantiate(root);stage.name="Underpass Repair Staging";SceneManager.MoveGameObjectToScene(stage,scene);if(PrefabUtility.IsPartOfPrefabInstance(stage))PrefabUtility.UnpackPrefabInstance(stage,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var sites=new[]{Define(stage,"polySurface853","polySurface838","polySurface906",true),Define(stage,"polySurface863","polySurface871","polySurface923",true)};foreach(var row in sites[0].rows){row.a.p.y=sites[0].y+(row.a.p.y-sites[0].y)*(5f/6f);row.b.p.y=sites[0].y+(row.b.p.y-sites[0].y)*(5f/6f);}var old=stage.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Sunken Road Underpasses");UnityEngine.Object.DestroyImmediate(old.gameObject);var group=new GameObject("Sunken Road Underpasses");group.transform.SetParent(stage.transform,false);var concrete=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/Tunnel Concrete.mat");var metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/DrivingLayout/Bridge Guardrail.mat");var changes=new List<Change>();int triangles=0;
for(int i=0;i<sites.Length;i++){var s=sites[i];triangles+=Continuous(s,group.transform,stage.transform,i+1,concrete,metal);foreach(var f in new[]{s.a,s.b}){var m=Outside(f,s);Assign(f,m);changes.Add(new Change{f=f,mesh=m});}float maxSlope=0;for(int r=1;r<s.rows.Count;r++){var a=(s.rows[r-1].a.p+s.rows[r-1].b.p)/2;var b=(s.rows[r].a.p+s.rows[r].b.p)/2;float horizontal=Vector2.Distance(new Vector2(a.x,a.z),new Vector2(b.x,b.z));if(horizontal>.01f)maxSlope=Mathf.Max(maxSlope,Mathf.Abs(b.y-a.y)/horizontal);}log.AppendLine("Underpass "+(i+1)+": continuous road, aligned wall and floor edges, existing atlas texture, slope="+(maxSlope*100).ToString("F2")+"%.");}
