static Site InstalledSite(GameObject root,int index){string junction=index==0?"polySurface906":"polySurface923";var module=root.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Sunken Underpass "+(index+1)+" - "+junction);var f=module.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name=="Continuous underpass roadway");var d=Read(f);var roof=module.GetComponentsInChildren<BoxCollider>(true).Single(c=>c.name=="Roof collision");var s=new Site{a=f,b=f,j=root.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name==junction),junction=junction,x=index==1};s.y=s.j.GetComponent<Renderer>().bounds.center.y;s.start=d.p.Min(s.L);s.end=d.p.Max(s.L);s.gapA=s.L(roof.bounds.min);s.gapB=s.L(roof.bounds.max);s.center=(s.gapA+s.gapB)/2;s.side=s.C(roof.bounds.center);var clusters=new List<List<float>>();foreach(float l in d.p.Select(s.L).OrderBy(v=>v)){if(clusters.Count==0||l-clusters.Last()[0]>.02f)clusters.Add(new List<float>());clusters.Last().Add(l);}foreach(var cluster in clusters){float l=(cluster.Min()+cluster.Max())/2;var row=Cross(s,d,l);row.a.p=s.P(l,s.C(row.a.p),row.a.p.y);row.b.p=s.P(l,s.C(row.b.p),row.b.p.y);if(Vector3.Distance(row.a.p,row.b.p)<25)throw new Exception("Road cross section narrowed at "+l);s.rows.Add(row);}s.start=s.L(s.rows[0].a.p);s.end=s.L(s.rows.Last().a.p);s.width=s.rows.Max(r=>Vector3.Distance(r.a.p,r.b.p));return s;}
