static int UpperCheck(GameObject root,Site[] sites){Physics.SyncTransforms();int count=0;foreach(var s in sites)foreach(float lane in new[]{-10.5f,-3.5f,3.5f,10.5f})for(float c=s.side-28;c<=s.side+28;c+=2){var p=s.P(s.center+lane,c,s.y);var hits=Physics.RaycastAll(p+Vector3.up*.5f,Vector3.down,1.2f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(root.transform)).OrderBy(h=>h.distance).ToArray();if(hits.Length==0||Mathf.Abs(hits[0].point.y-s.y)>.15f)throw new Exception("Upper crossing discontinuity at "+p+" hit="+(hits.Length>0?hits[0].collider.name:"none"));if(Physics.OverlapCapsule(p+Vector3.up*1.8f,p+Vector3.up*2.1f,1.45f,~0,QueryTriggerInteraction.Ignore).Any(collider=>collider.transform.IsChildOf(root.transform)))throw new Exception("Upper road blocked at "+p);count++;}return count;}
static void Refine(){var log=new StringBuilder();GameObject stage=null;try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeUnderpassRefine-"+stamp+".unity",true);File.Copy(PrefabPath,"FinalEnvironmentRoadBackup/BeforeUnderpassRefine-"+stamp+".prefab");stage=UnityEngine.Object.Instantiate(root);stage.name="Underpass Upper Road Refinement";SceneManager.MoveGameObjectToScene(stage,scene);if(PrefabUtility.IsPartOfPrefabInstance(stage))PrefabUtility.UnpackPrefabInstance(stage,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var sites=new[]{InstalledSite(stage,0),InstalledSite(stage,1)};var old=stage.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Sunken Road Underpasses");old.gameObject.SetActive(false);var group=new GameObject("Sunken Road Underpasses");group.transform.SetParent(stage.transform,false);var concrete=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/Tunnel Concrete.mat");var metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/DrivingLayout/Bridge Guardrail.mat");int triangles=0;for(int i=0;i<2;i++)triangles+=Continuous(sites[i],group.transform,stage.transform,i+1,concrete,metal);UnityEngine.Object.DestroyImmediate(old.gameObject);var upperFixed=EnsureUpperFloors(stage,sites).Select(f=>f.name).ToArray();int lower=Validate(stage,sites),upper=UpperCheck(stage,sites);
