foreach(var fixedFloor in upperFixed){var f=root.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name==fixedFloor);var c=f.GetComponent<MeshCollider>();if(!c)c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;c.enabled=true;c.isTrigger=false;PrefabUtility.RecordPrefabInstancePropertyModifications(c);}int trees=0;var treeRoots=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>(r.name+" "+string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name))).ToLowerInvariant().Contains("palm")||(r.name+" "+string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name))).ToLowerInvariant().Contains("tree")).Select(r=>PrefabUtility.GetNearestPrefabInstanceRoot(r.gameObject)).Where(g=>g&&!g.transform.IsChildOf(root.transform)).Distinct().ToArray();foreach(var tree in treeRoots){var rs=tree.GetComponentsInChildren<Renderer>(true);if(rs.Length==0)continue;var bounds=rs[0].bounds;foreach(var r in rs.Skip(1))bounds.Encapsulate(r.bounds);if(bounds.size.x>35||bounds.size.z>35)continue;var foot=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);foreach(var s in sites){if(s.L(foot)<s.gapA||s.L(foot)>s.gapB||s.C(foot)<SideEdge(s,s.center,false)-2||s.C(foot)>SideEdge(s,s.center,true)+2)continue;var destination=s.P(s.center,SideEdge(s,s.center,true)+20,s.y);tree.transform.position+=destination-foot;PrefabUtility.RecordPrefabInstancePropertyModifications(tree.transform);trees++;break;}}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed.");log.AppendLine("SUCCESS: upper-road wall crossings lowered below asphalt; lower checks="+lower+"; upper-road floor and vehicle checks="+upper+"; upper road colliders repaired="+upperFixed.Length+"; relocated roof-intersecting trees="+trees+"; triangles="+triangles+"; six structure renderers; existing materials only; scene and prefab saved.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}finally{if(stage)UnityEngine.Object.DestroyImmediate(stage);File.WriteAllText("FinalEnvironmentRoadReview/UnderpassRefineReport.txt",log.ToString());}}
static void FinalCheck(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var sites=new[]{InstalledSite(root,0),InstalledSite(root,1)};int lower=Validate(root,sites),upper=UpperCheck(root,sites);var candidates=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(root.transform)).ToArray();foreach(var s in sites)foreach(var r in candidates){var b=r.bounds;var p=new Vector3(b.center.x,b.min.y,b.center.z);if(b.size.y>2&&b.size.y<30&&b.size.x<18&&b.size.z<18&&b.min.y<s.y-1&&b.max.y>s.y-.8f&&s.L(p)>s.gapA&&s.L(p)<s.gapB&&s.C(p)>SideEdge(s,s.L(p),false)&&s.C(p)<SideEdge(s,s.L(p),true))log.AppendLine("ROOF PROP "+r.name+" parent="+(r.transform.parent?r.transform.parent.name:"none")+" bounds="+b);}
int shaders=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().Sum(m=>ShaderUtil.GetShaderMessages(m.shader).Count(v=>v.severity.ToString()=="Error"));var water=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(f=>f.name=="Water");var wd=Read(water);int dry=0;foreach(var s in sites)foreach(var row in s.rows)foreach(float t in new[]{.05f,.25f,.5f,.75f,.95f}){var p=Vector3.Lerp(row.a.p,row.b.p,t);if(Height(wd,p,out float y)&&y>p.y+.02f)throw new Exception("Water overlaps road.");dry++;}if(shaders!=0)throw new Exception("Shader errors.");log.AppendLine("SUCCESS: saved-scene lower floor and space checks="+lower+"; upper road checks="+upper+"; dry-road samples="+dry+"; shader errors="+shaders+".");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/UnderpassFinalCheck.txt",log.ToString());}
static void Preview(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");for(int i=0;i<2;i++){string junction=i==0?"polySurface906":"polySurface923";var f=root.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name==junction);var p=f.GetComponent<Renderer>().bounds.center;var dir=i==0?Vector3.forward:Vector3.right;Capture(scene,p-dir*100+Vector3.up*12,p-dir*4-Vector3.up*3,"Sunken-Underpass-"+(i+1));Capture(scene,p-dir*150+Vector3.up*65,p-Vector3.up*2,"Sunken-Underpass-"+(i+1)+"-Overview");}log.AppendLine("Preview complete; lower floor and upper crossing inspected.");}catch(Exception e){log.AppendLine(e.ToString());}File.WriteAllText("FinalEnvironmentRoadReview/SunkenPreviewReport.txt",log.ToString());}
static void Capture(Scene scene,Vector3 p,Vector3 target,string name){var go=new GameObject("Underpass preview camera"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(go,scene);var c=go.AddComponent<Camera>();c.enabled=false;c.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p));c.nearClipPlane=.2f;c.farClipPlane=5000;c.fieldOfView=62;var rt=RenderTexture.GetTemporary(1600,1100,24);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1600,1100,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,1100),0,0);t.Apply();File.WriteAllBytes("FinalEnvironmentRoadReview/"+name+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=old;c.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}
}



















